				}
				if (!list2.Contains(relateIO))
				{
					list2.Add(relateIO);
				}
			}
			if (list.Count == 1 && Childs.Count == list2.Count)
			{
				return IsSuitable(TypeName, list[0].TypeName) ? list[0] : null;
			}
